const version = "14.0.6";
try {
  if (args[0]?.macroPass !== "postActiveEffects") return;
  const target = workflow?.hitTargets?.first();
  if (!target) return;
  const tactor = target.actor;
  if (!tactor) return;
  // stackable: "count" — DAE auto-increments flags.dae.stacks when the same effect
  // (matched by origin + base name) is re-applied, so this stays a single effect.
  // midi-qol's OverTime processor multiplies damageRoll by flags.dae.stacks at tick time,
  // and a successful save removes the whole effect (all stacks).
  await MidiQOL.socket().executeAsGM("createEffects", {
    actorUuid: tactor.uuid,
    effects: [{
      name: "Wounded",
      img: macroItem?.img ?? "icons/skills/wounds/injury-pain-blood-red.webp",
      origin: macroItem?.uuid,
      flags: { dae: { stackable: "count", stacks: 1 } },
      changes: [{
        key: "flags.midi-qol.OverTime",
        value: "turn=start,damageRoll=1d4,damageType=necrotic,saveDC=15,saveAbility=con,saveRemove=true,label=Wounded",
        mode: 0,
        priority: 20
      }]
    }]
  });
} catch (err) {
  console.error(`Wounding ${version}`, err);
}
